		auto phase = [&](bool p_undo_enabled) {
			text_edit->set_undo_enabled(p_undo_enabled);
			CHECK(text_edit->is_undo_enabled() == p_undo_enabled);
			CHECK_FALSE(text_edit->has_undo());
			CHECK_FALSE(text_edit->has_redo());

			String old_text = text_edit->get_text();
			String new_text = old_text + "x";

			text_edit->insert_text_at_caret("x");
			CHECK(text_edit->get_text() == new_text);
			CHECK(text_edit->has_undo() == p_undo_enabled);
			CHECK_FALSE(text_edit->has_redo());
			text_edit->undo();
			CHECK(text_edit->get_text() == (p_undo_enabled ? old_text : new_text));
			CHECK_FALSE(text_edit->has_undo());
			CHECK(text_edit->has_redo() == p_undo_enabled);
			text_edit->redo();
			CHECK(text_edit->get_text() == new_text);
			CHECK(text_edit->has_undo() == p_undo_enabled);
			CHECK_FALSE(text_edit->has_redo());
		};

		phase(true);
		phase(false);
		phase(true);
